INSERT OR REPLACE INTO content (key, value, updated_at) VALUES ('domains', '[{"id":"intel","label":{"en":"INTELLIGENCE","id":"INTELIJEN"},"y":60},{"id":"gov","label":{"en":"GOVERNANCE","id":"TATA KELOLA"},"y":193},{"id":"work","label":{"en":"WORKFORCE","id":"KEPEGAWAIAN"},"y":347},{"id":"comm","label":{"en":"COMMERCE","id":"NIAGA"},"y":460}]', 1785445037);
INSERT OR REPLACE INTO content (key, value, updated_at) VALUES ('projects', '[{"id":"exec","pdf":"/porto/executive-dashboard.pdf","dom":"intel","y":59,"live":true,"year":"2025","ongoing":true,"name":"Executive Dashboard","runtime":["laravel@11.36.1","php@8.2.24","postgresql"],"org":"Kementerian BUMN","role":{"en":"Full-stack developer","id":"Full-stack developer"},"domain":{"en":"Executive intelligence","id":"Intelijen eksekutif"},"sum":{"en":"A single screen the ministry''s leadership opens to see the whole state-owned enterprise portfolio: every parent company, each entity across the groups, operational status, and the ownership structure underneath each one.","id":"Satu layar yang dibuka pimpinan kementerian untuk melihat seluruh portofolio BUMN: seluruh perusahaan induk, tiap entitas grup, status operasional, dan struktur kepemilikan di bawah masing-masing."},"hi":{"en":["Rolled every group entity into one live counter set without slowing the first paint.","Drew the ownership tree as an interactive org chart — parent, subsidiary, affiliate, down several levels.","Per-company drill-down: profile, group structure, subsidiaries, board of directors and commissioners.","Aggregations pushed into PostgreSQL views so the dashboard reads instead of computes."],"id":["Menggabungkan seluruh entitas grup jadi satu set counter live tanpa memperlambat first paint.","Menggambar pohon kepemilikan sebagai org chart interaktif — induk, anak, afiliasi, sampai beberapa tingkat.","Drill-down per perusahaan: profil, struktur grup, anak perusahaan, direksi dan komisaris.","Agregasi didorong ke PostgreSQL view supaya dashboard membaca, bukan menghitung."]},"screens":{"en":["Executive dashboard","BUMN data dashboard","Company profile","Group structure","Subsidiaries & affiliates","Board of directors"],"id":["Dashboard eksekutif","Dashboard data BUMN","Profil perusahaan","Struktur grup","Anak & afiliasi","Dewan direksi"]},"sketch":"donut"},{"id":"egrc","pdf":"/porto/egrc.pdf","dom":"gov","y":140,"live":true,"year":"2023","ongoing":true,"name":"EGRC","runtime":["laravel@9.52.16","php@8.2.3","postgresql"],"org":"Kementerian BUMN","role":{"en":"Full-stack developer","id":"Full-stack developer"},"domain":{"en":"Governance, risk & compliance","id":"Tata kelola, risiko & kepatuhan"},"sum":{"en":"Enterprise Governance Risk Compliance — where every state-owned enterprise files its governance reports (internal audit, GCG, audit-board findings, board reports) and the ministry tracks what is still outstanding.","id":"Enterprise Governance Risk Compliance — tempat setiap BUMN menyerahkan laporan tata kelolanya (audit internal, GCG, temuan BPK, laporan direksi) dan kementerian memantau apa yang masih tertunggak."},"hi":{"en":["Submission pipeline with per-document status: draft, filed, verified, returned.","Filters by year, period and company so a reviewer reaches one filing in three clicks.","Sits behind Satu BUMN, the shared portal that also fronts Korespondensi and SiLaba.","Role-scoped access — ministry reviewers and enterprise submitters see different halves."],"id":["Alur pengajuan dengan status per dokumen: draft, terkirim, terverifikasi, dikembalikan.","Filter tahun, periode, dan perusahaan supaya verifikator sampai ke satu berkas dalam tiga klik.","Berada di balik Satu BUMN, portal bersama yang juga menaungi Korespondensi dan SiLaba.","Akses berbasis peran — verifikator kementerian dan pengirim BUMN melihat sisi berbeda."]},"screens":{"en":["Satu BUMN portal","Submission register","Verification queue","Report attachments"],"id":["Portal Satu BUMN","Daftar pengajuan","Antrean verifikasi","Lampiran laporan"]},"sketch":"portal"},{"id":"koresp","pdf":"/porto/korespondensi.pdf","dom":"gov","y":192,"live":true,"year":"2023","ongoing":true,"name":"Korespondensi","runtime":["laravel@9.52.16","php@8.2.3","postgresql"],"org":"Kementerian BUMN","role":{"en":"Full-stack developer","id":"Full-stack developer"},"domain":{"en":"Official correspondence","id":"Korespondensi resmi"},"sum":{"en":"Dispatch and receipt of official letters between the ministry and every state-owned enterprise. Every letter is traceable from draft to receipt.","id":"Pengiriman dan penerimaan surat dinas antara kementerian dan seluruh BUMN. Tiap surat bisa ditelusuri dari draf sampai diterima."},"hi":{"en":["Two dashboards, two audiences — the ministry''s view and each enterprise''s view of the same ledger.","Quarterly and monthly volume trends, plus letter status split (draft, sent, received, disposed).","Per-enterprise breakdown so a slow responder is visible without asking anyone.","Charts fed by PostgreSQL aggregate views, cached per quarter."],"id":["Dua dashboard, dua audiens — sudut pandang kementerian dan tiap BUMN atas buku yang sama.","Tren volume triwulanan dan bulanan, plus pembagian status surat (draf, kirim, terima, disposisi).","Rincian per BUMN sehingga yang lambat merespons terlihat tanpa perlu ditanya.","Grafik disuplai view agregat PostgreSQL, di-cache per triwulan."]},"screens":{"en":["Ministry dashboard","Enterprise dashboard","Outgoing register","Incoming register"],"id":["Dashboard kementerian","Dashboard BUMN","Register surat keluar","Register surat masuk"]},"sketch":"line"},{"id":"silaba","pdf":"/porto/silaba.pdf","dom":"gov","y":244,"live":true,"year":"2023","ongoing":true,"name":"SiLaba","runtime":["laravel@9.52.16","php@8.2.3","postgresql"],"org":"Kementerian BUMN","role":{"en":"Full-stack developer","id":"Full-stack developer"},"domain":{"en":"Periodic reporting","id":"Pelaporan berkala"},"sum":{"en":"Sistem Informasi Laporan Berkala. Enterprises upload their periodic filings — financial statements, management reports, cover letters — and ministry staff verify each one against the period it belongs to.","id":"Sistem Informasi Laporan Berkala. BUMN mengunggah laporan berkalanya — laporan keuangan, laporan manajemen, surat pengantar — dan staf kementerian memverifikasi tiap berkas sesuai periodenya."},"hi":{"en":["Report register and a separate verification queue, so filing and reviewing never collide.","Per-document status pills and an audit log of every status change.","Attachment handling for multi-file filings with a cover letter and supporting documents.","Search across company, year and quarter."],"id":["Register laporan dan antrean verifikasi terpisah, supaya pengiriman dan peninjauan tidak bertabrakan.","Pil status per dokumen dan log audit untuk tiap perubahan status.","Penanganan lampiran untuk berkas multi-file dengan surat pengantar dan dokumen pendukung.","Pencarian lintas perusahaan, tahun, dan triwulan."]},"screens":{"en":["BUMN reports","Report verification","Attachment viewer"],"id":["Laporan BUMN","Verifikasi laporan","Penampil lampiran"]},"sketch":"table"},{"id":"simanis","pdf":"/porto/simanis.pdf","dom":"work","y":320,"live":true,"year":"2023","ongoing":true,"name":"Simanis","runtime":["laravel@5.5.50","php@7.1.26","postgresql"],"org":"Kementerian BUMN","role":{"en":"Maintainer & feature developer","id":"Maintainer & pengembang fitur"},"domain":{"en":"Workforce management","id":"Manajemen kepegawaian"},"sum":{"en":"The ministry''s personnel system, and the oldest codebase I look after — Laravel 5.5 on PHP 7.1. Travel orders, accountability, and the annual and semiannual performance reviews for every employee.","id":"Sistem kepegawaian kementerian, dan basis kode tertua yang saya pegang — Laravel 5.5 di PHP 7.1. Surat tugas, pertanggungjawaban, serta penilaian kinerja tahunan dan semesteran seluruh pegawai."},"hi":{"en":["Travel orders end to end: administration, nominative cost breakdown, accountability, PDF output.","SKP performance review with a rating distribution chart per work unit.","Approval realisation tracking — who has signed, who has not.","Added features to a legacy stack without triggering a rewrite the ministry did not ask for."],"id":["Surat tugas ujung ke ujung: administrasi, rincian nominatif, pertanggungjawaban, keluaran PDF.","Penilaian kinerja SKP dengan grafik distribusi nilai per unit kerja.","Pelacakan realisasi persetujuan — siapa sudah tanda tangan, siapa belum.","Menambah fitur di stack legacy tanpa memicu rewrite yang tidak diminta kementerian."]},"screens":{"en":["Travel order — administration","Travel order — accountability","Travel order — nominative","SKP annual distribution","SKP semiannual distribution","Approval realisation"],"id":["Surat tugas — administrasi","Surat tugas — pertanggungjawaban","Surat tugas — nominatif","Distribusi SKP tahunan","Distribusi SKP semesteran","Realisasi persetujuan"]},"sketch":"curve"},{"id":"simo","pdf":"/porto/simanis-mobile.pdf","dom":"work","y":372,"live":true,"year":"2024","ongoing":true,"name":"Simanis Mobile (SIMO)","runtime":["swift@5","ios","xcode"],"org":"Kementerian BUMN","role":{"en":"iOS developer","id":"iOS developer"},"domain":{"en":"Workforce, in the pocket","id":"Kepegawaian, di saku"},"sum":{"en":"Simanis in an employee''s hand. Clock in from the office or from wherever work is happening, check remaining leave, find a colleague, scan into a meeting.","id":"Simanis dalam genggaman pegawai. Absen dari kantor atau dari mana pun pekerjaan berlangsung, cek sisa cuti, cari rekan kerja, scan masuk rapat."},"hi":{"en":["Attendance with map-based location check — the app confirms you are inside the office radius before it lets you clock in.","Home screen carrying today''s shift, clock-in and clock-out times, and accumulated lateness.","Directory of every state-owned enterprise with drill-down into commissioners and directors.","Leave balance, meeting QR, calendar and birthdays in one tab bar."],"id":["Absensi dengan pemeriksaan lokasi berbasis peta — aplikasi memastikan Anda di dalam radius kantor sebelum bisa presensi.","Layar utama memuat shift hari ini, jam masuk dan pulang, serta akumulasi keterlambatan.","Direktori seluruh BUMN dengan drill-down ke komisaris dan direksi.","Sisa cuti, QR rapat, kalender, dan ulang tahun dalam satu tab bar."]},"screens":{"en":["Dashboard","Attendance & geofence","BUMN search","BUMN detail"],"id":["Dashboard","Presensi & geofence","Pencarian BUMN","Detail BUMN"]},"sketch":"phone"},{"id":"kuffa","pdf":"/porto/kuffa.pdf","dom":"comm","y":459,"live":false,"year":"2022","name":"Kuffa","runtime":["django@3.1","python@3.9","midtrans"],"org":"STMIK Jayakarta","role":{"en":"Sole developer — final thesis","id":"Pengembang tunggal — tugas akhir"},"domain":{"en":"Fashion e-commerce","id":"E-commerce fesyen"},"sum":{"en":"My thesis: a working fashion store, not a mockup of one. Catalogue, cart, checkout, and real money moving through Midtrans.","id":"Tugas akhir saya: toko fesyen yang benar-benar jalan, bukan tiruannya. Katalog, keranjang, checkout, dan uang sungguhan lewat Midtrans."},"hi":{"en":["Midtrans Snap checkout covering QRIS, bank virtual accounts and cards.","Order confirmation emails dispatched over SMTP once payment settles.","Catalogue and cart modelled with the Django ORM.","The project that turned coursework into something I could hand to a stranger."],"id":["Checkout Midtrans Snap mencakup QRIS, virtual account bank, dan kartu.","Email konfirmasi pesanan dikirim lewat SMTP begitu pembayaran lunas.","Katalog dan keranjang dimodelkan dengan Django ORM.","Proyek yang mengubah tugas kuliah jadi sesuatu yang bisa saya serahkan ke orang asing."]},"screens":{"en":["Landing","Catalogue","Product detail","Midtrans checkout"],"id":["Beranda","Katalog","Detail produk","Checkout Midtrans"]},"sketch":"grid"}]', 1785445037);
INSERT OR REPLACE INTO content (key, value, updated_at) VALUES ('layers', '[{"n":{"en":"Backend","id":"Backend"},"s":{"en":"Where I live","id":"Tempat saya tinggal"},"items":[["PHP",3,"php"],["Laravel",3,"laravel"],["Python",2,"python"],["Django",2,"django"],["CodeIgniter",2,"codeigniter"],["REST APIs",3]]},{"n":{"en":"Data","id":"Data"},"s":{"en":"Functions, views, relations","id":"Function, view, relasi"},"items":[["PostgreSQL",3,"postgresql"],["MySQL",2,"mysql"],["SQL (Advanced)",3],["RDBMS design",3]]},{"n":{"en":"Frontend","id":"Frontend"},"s":{"en":"Enough to finish the job","id":"Cukup untuk menuntaskan"},"items":[["JavaScript",2,"javascript"],["HTML",3,"html5"],["CSS",3,"css"],["Blade",3,"laravel"]]},{"n":{"en":"Mobile","id":"Mobile"},"s":{"en":"iOS, shipped once","id":"iOS, sudah pernah rilis"},"items":[["Swift",1,"swift"],["Xcode",2,"xcode"],["CoreLocation",1]]},{"n":{"en":"Quality","id":"Kualitas"},"s":{"en":"Where I started","id":"Titik awal saya"},"items":[["AppiumLibrary",2,"appium"],["Regression",3],["Smoke & sanity",3],["Test scenarios",3]]},{"n":{"en":"Practice","id":"Praktik"},"s":{"en":"How the work runs","id":"Cara kerja berjalan"},"items":[["Agile",3],["Monolithic architecture",3],["Legacy maintenance",3],["AI-assisted development",2],["System integration",2],["IT service reporting",2]]}]', 1785445037);
INSERT OR REPLACE INTO content (key, value, updated_at) VALUES ('timeline', '[{"g":"emp","s":"2021-08","e":"2022-01","who":"PT Vidio Dot Com","logo":"/logo/vidio.svg","role":{"en":"Test Engineer","id":"Test Engineer"}},{"g":"emp","s":"2023-03","e":null,"who":"Kementerian BUMN","logo":"/logo/kementerian-bumn.svg","role":{"en":"Junior Web Programmer","id":"Junior Web Programmer"}},{"g":"emp","s":"2024-01","e":null,"who":"PT Sinergi Informatika Semen Indonesia","logo":"/logo/sinergi-informatika.svg","role":{"en":"Developer Technician","id":"Developer Technician"}},{"g":"prog","s":"2022-02","e":"2022-07","who":"Binar Academy","logo":"/logo/binar-academy.svg","soft":true,"role":{"en":"iOS Developer · MSIB Batch 2","id":"iOS Developer · MSIB Batch 2"}},{"g":"edu","s":"2018-09","e":"2022-08","who":"STMIK Jayakarta","logo":"/logo/stmik-jayakarta.svg","soft":true,"role":{"en":"B.Eng Informatics · GPA 3.85","id":"S.Kom Teknik Informatika · IPK 3,85"}},{"g":"edu","s":"2020-01","e":"2020-12","who":"WASENJA","logo":"/logo/wasenja.svg","soft":true,"role":{"en":"Member","id":"Anggota"}}]', 1785445037);
INSERT OR REPLACE INTO content (key, value, updated_at) VALUES ('i18n', '{"nav.map":["Map","Peta"],"nav.profile":["Profile","Profil"],"nav.path":["Path","Jejak"],"nav.work":["Work","Karya"],"nav.stack":["Stack","Stack"],"nav.contact":["Contact","Kontak"],"hero.avail":["Open to selected work","Terbuka untuk pekerjaan terpilih"],"hero.thesis":["Most of what I build has <b>no public URL</b>. They are internal systems for the Indonesian state — payroll, risk, correspondence, official letters. So this page does not pretend to be a product gallery. It reconstructs them as drawings.","Sebagian besar yang saya bangun <b>tidak punya URL publik</b>. Semuanya sistem internal negara — kepegawaian, risiko, korespondensi, surat dinas. Jadi halaman ini tidak berpura-pura jadi galeri produk. Ia merekonstruksinya sebagai gambar teknik."],"k.role":["Role","Peran"],"v.role":["Developer Technician","Developer Technician"],"k.posted":["Posted to","Ditempatkan di"],"k.via":["Via","Melalui"],"k.since":["Since","Sejak"],"map.title":["Fig. 1 — Systems built &amp; maintained","Gbr. 1 — Sistem yang dibangun &amp; dirawat"],"map.hint":["Select a node to open its drawing","Pilih node untuk membuka gambarnya"],"map.live":["In production","Berjalan di produksi"],"map.archived":["Academic / archived","Akademik / arsip"],"map.note":["Screens redrawn · figures withheld","Layar digambar ulang · angka disamarkan"],"s.shipped":["Systems shipped","Sistem dirilis"],"s.gov":["Running inside Kementerian BUMN","Berjalan di Kementerian BUMN"],"s.runtimes":["Runtimes in production","Runtime di produksi"],"s.gpa":["GPA / 4.00","IPK / 4,00"],"h.profile":["Profile","Profil"],"p.slot":["Portrait slot<br>3:4 · 900×1200","Slot foto<br>3:4 · 900×1200"],"p.b1":["I write software that civil servants open every morning. Attendance, performance reviews, official letters, periodic reports from every state-owned enterprise — unglamorous work, with the quiet requirement that it cannot be down.","Saya menulis perangkat lunak yang dibuka aparatur sipil setiap pagi. Presensi, penilaian kinerja, surat dinas, laporan berkala dari seluruh BUMN — pekerjaan yang tidak glamor, dengan satu syarat diam-diam: tidak boleh mati."],"p.b2":["I came into development sideways: my first role was test engineer at Vidio, breaking mobile apps for a living. That order turned out to be useful. I still think in edge cases first, and I write the regression path before I write the feature.","Saya masuk ke pengembangan lewat pintu samping: peran pertama saya test engineer di Vidio, kerjanya merusak aplikasi mobile. Urutan itu ternyata berguna. Saya masih berpikir dari edge case dulu, dan menulis jalur regresi sebelum menulis fiturnya."],"k.base":["Base","Domisili"],"k.disc":["Discipline","Disiplin"],"v.disc":["Full-stack · Government systems","Full-stack · Sistem pemerintahan"],"k.edu":["Education","Pendidikan"],"v.edu":["STMIK Jayakarta — B.Eng, Informatics","STMIK Jayakarta — S.Kom, Teknik Informatika"],"k.gpa":["GPA","IPK"],"k.lang":["Languages","Bahasa"],"v.lang":["Indonesian (native) · English (conversational)","Indonesia (ibu) · Inggris (percakapan)"],"k.method":["Practice","Praktik"],"v.method":["Agile · Monolithic architecture · AI-assisted development","Agile · Arsitektur monolitik · Pengembangan dibantu AI"],"h.path":["Path","Jejak"],"h.pathsub":["Two concurrent postings since 2024","Dua penempatan bersamaan sejak 2024"],"g.emp":["Employment","Pekerjaan"],"g.prog":["Programs","Program"],"g.edu":["Education","Pendidikan"],"m.jwp":["Junior Web Programmer","Junior Web Programmer"],"m.dt":["Developer Technician","Developer Technician"],"m.beng":["B.Eng Informatics · GPA 3.85","S.Kom Teknik Informatika · IPK 3,85"],"r1.t":["Developer Technician","Developer Technician"],"r1.org":["PT Sinergi Informatika Semen Indonesia · 2024 → present","PT Sinergi Informatika Semen Indonesia · 2024 → sekarang"],"r2.org":["Kementerian BUMN · 2023 → present","Kementerian BUMN · 2023 → sekarang"],"r3.org":["PT Vidio Dot Com · 2021 – 2022","PT Vidio Dot Com · 2021 – 2022"],"r1.a":["Built the Simanis Mobile (SIMO) iOS app in Swift — attendance with geofenced check-in, employee directory, meeting QR.","Membangun aplikasi iOS Simanis Mobile (SIMO) dengan Swift — presensi dengan geofence, direktori pegawai, QR rapat."],"r1.b":["Maintained the Laravel systems already in production at the ministry.","Merawat sistem Laravel yang sudah berjalan di produksi kementerian."],"r1.c":["Modelled data in PostgreSQL using functions, views and relations.","Memodelkan data di PostgreSQL memakai function, view, dan relasi."],"r2.t":["Junior Web Programmer","Junior Web Programmer"],"r2.a":["Developed and maintained internal and public-facing ministry applications on Laravel.","Mengembangkan dan merawat aplikasi internal maupun publik kementerian di atas Laravel."],"r2.b":["Watched and hardened the critical paths — the screens that stop work when they break.","Memantau dan memperkuat jalur kritis — layar yang menghentikan pekerjaan begitu rusak."],"r2.c":["Documented every feature as a user story before building it.","Mendokumentasikan tiap fitur sebagai user story sebelum dibangun."],"r3.t":["Test Engineer","Test Engineer"],"r3.a":["Tested mobile releases: manual, regression, sanity and smoke passes.","Menguji rilis mobile: manual, regresi, sanity, dan smoke."],"r3.b":["Wrote scenarios and automated them with AppiumLibrary.","Menulis skenario dan mengotomatiskannya dengan AppiumLibrary."],"r3.c":["Filed the defect reports that came out of each cycle.","Membuat laporan bug dari tiap siklus pengujian."],"h.work":["Register of systems","Register sistem"],"c.system":["System","Sistem"],"c.runtime":["Runtime","Runtime"],"c.domain":["Domain","Domain"],"c.year":["Year","Tahun"],"h.stack":["Stack, by layer","Stack, per lapis"],"d.core":["Daily / production","Harian / produksi"],"d.work":["Working knowledge","Cukup menguasai"],"d.learn":["Learning","Sedang dipelajari"],"h.qa":["I started by breaking things","Saya mulai dengan merusak"],"q.b1":["Before I shipped features I tested other people''s. Six months at Vidio running release cycles on the mobile apps taught me what a defect looks like before a user finds it.","Sebelum merilis fitur sendiri, saya menguji fitur orang lain. Enam bulan di Vidio menjalankan siklus rilis aplikasi mobile mengajari saya seperti apa rupa cacat sebelum pengguna menemukannya."],"q.b2":["It is the reason my Laravel work carries verification steps in the user story, not just an acceptance line.","Itu sebabnya pekerjaan Laravel saya membawa langkah verifikasi di dalam user story, bukan sekadar satu baris acceptance."],"q.s1":["Manual","Manual"],"q.d1":["Exploratory passes against the story''s acceptance criteria.","Penelusuran eksploratif terhadap kriteria penerimaan story."],"q.s2":["Automation","Otomasi"],"q.d2":["Scenarios scripted and run with AppiumLibrary.","Skenario diskrip dan dijalankan dengan AppiumLibrary."],"q.s3":["Regression","Regresi"],"q.d3":["Every prior path re-run before a release is tagged.","Semua jalur lama dijalankan ulang sebelum rilis ditandai."],"q.s4":["Sanity &amp; smoke","Sanity &amp; smoke"],"q.d4":["Fast gates on the build — does it start, does the core path hold.","Gerbang cepat pada build — apakah jalan, apakah jalur inti bertahan."],"h.cred":["Certified","Sertifikasi"],"cr.msib1":["MSIB Internship — Vidio","Magang MSIB — Vidio"],"cr.msib2":["MSIB Independent Study — Binar Academy","Studi Independen MSIB — Binar Academy"],"h.contact":["Send a brief","Kirim kebutuhanmu"],"f.name":["Name","Nama"],"f.email":["Email","Email"],"f.msg":["What do you need built?","Apa yang perlu dibangun?"],"f.turnstile":["Turnstile mounts here — bot check, no puzzle","Turnstile dipasang di sini — cek bot, tanpa teka-teki"],"f.send":["Transmit","Kirim"],"f.ok":["Received","Diterima"],"f.okb":["I read everything that comes in and reply within two working days.","Semua yang masuk saya baca dan saya balas dalam dua hari kerja."],"f.cv":["Curriculum vitae","Curriculum vitae"],"f.cvv":["Download PDF ↓","Unduh PDF ↓"],"t.drawn":["Drawn by","Digambar oleh"],"t.sheet":["Sheet","Lembar"],"t.rev":["Revision","Revisi"],"t.served":["Served from","Dilayani dari"],"t.views":["Views","Kunjungan"],"t.foot":["Built in Jakarta. No tracking beyond a page counter.","Dibuat di Jakarta. Tanpa pelacakan selain penghitung kunjungan."],"dr.about":["About","Tentang"],"dr.hi":["What it does","Apa yang dikerjakan"],"dr.screens":["Screens","Layar"],"dr.org":["Client","Klien"],"dr.role":["Role","Peran"],"dr.status":["Status","Status"],"dr.live":["In production","Berjalan di produksi"],"dr.idle":["Archived","Arsip"],"dr.year":["In service","Masa pakai"],"dr.pdf":["Open full portfolio (PDF)","Buka portofolio lengkap (PDF)"],"t.present":["present","sekarang"],"dr.fig":["Fig. — interface schematic, redrawn","Gbr. — skema antarmuka, digambar ulang"]}', 1785445037);
